struct modinfo{ui mod, root;};
template<modinfo const&ref>
struct modular{
	static constexpr ui const& MOD = ref.mod;
	static modular root(){ return modular(ref.root); }
	ui val;
	modular(i64 v = 0){ normalize(v % MOD + MOD); }
	modular& normalize(ui v){
		val = v < MOD ? v : v - MOD;
		return *this;
	}
	modular operator-() const{ return modular() - *this; }
	modular& operator+=(const modular& rhs){ return normalize(val + rhs.val); }
	modular& operator-=(const modular& rhs){ return normalize(val + MOD - rhs.val); }
	modular& operator*=(const modular& rhs){
		val = (ull)val * rhs.val % MOD;
		return *this;
	}
	modular& operator/=(const modular& rhs){ return *this *= rhs.inv(); }
	modular operator+(const modular& rhs) const{ return modular(*this) += rhs; }
	modular operator-(const modular& rhs) const{ return modular(*this) -= rhs; }
	modular operator*(const modular& rhs) const{ return modular(*this) *= rhs; }
	modular operator/(const modular& rhs) const{ return modular(*this) /= rhs; }
	modular pow(int e) const{
		modular base(*this), res(1);
		while(e){
			if(e & 1) res *= base;
			base *= base;
			e >>= 1;
		}
		return res;
	}
	modular inv() const{ return pow(MOD - 2); }
	friend modular operator+(int x, const modular& y){ return modular(x) + y; }
	friend modular operator-(int x, const modular& y){ return modular(x) - y; }
	friend modular operator*(int x, const modular& y){ return modular(x) * y; }
	friend modular operator/(int x, const modular& y){ return modular(x) / y; }
	friend ostream& operator<<(ostream& os, const modular& m){ return os << m.val; }
	friend istream& operator>>(istream& is, modular& m){ i64 x; is >> x; m = modular(x); return is; }
	bool operator<(const modular& r) const{ return val < r.val; }
	bool operator==(const modular& r) const{ return val == r.val; }
	bool operator!=(const modular& r) const{ return val != r.val; }
	explicit operator bool() const{ return val; }
};

modinfo base_mod{998244353, 3};
using mint = modular<base_mod>;

const int MAX_FAC = 10010;
mint fact[MAX_FAC], inv_fact[MAX_FAC], inv_table[MAX_FAC];
void init_fac(){
	fact[0] = 1;
	loop(i, 1, MAX_FAC){
		fact[i] = fact[i - 1] * i;
	}
	inv_fact[MAX_FAC - 1] = fact[MAX_FAC - 1].inv();
	for(int i = MAX_FAC - 2; i >= 0; --i){
		inv_fact[i] = inv_fact[i + 1] * (i + 1);
	}
	for(int i = MAX_FAC - 1; i >= 1; --i){
		inv_table[i] = inv_fact[i] * fact[i - 1];
	}
}
mint comb(int n, int k){
	return fact[n] * inv_fact[n - k] * inv_fact[k];
}
mint binomial(int a, int b){
	return fact[a + b] * inv_fact[a] * inv_fact[b];
}
mint catalan(int n){
	return binomial(n, n) - (n - 1 >= 0 ? binomial(n - 1, n + 1) : 0);
}

void solve(){
	int n, m; cin >> n >> m >> base_mod.mod;
	init_fac();

	mint res;
	loop(len, 1, m){
		mint t1 = mint(len + 1).pow(len) * len / (n - len) * inv_fact[len];
		rep(i, m - len){
			int j = i + len;
			mint t2 = mint(n - len).pow(i) * inv_fact[i];
			mint t3 = (n - j) * mint(n + 1).pow(m - 1 - j) * fact[j];
			res += t1 * t2 * t3;
		}
	}
	res *= mint(2).pow(m - 1) * (n + 1 - m);
	print_out(res);
}

